//! 🪺️ The actual original registry transfers only paid handles, including its first cold admission.
use crate::{BoundedJob, JOBS, JOB_KIND_INFER, JOB_KIND_IO_SNIFF, JOB_SLOTS, JobBody, OriginalJobKindLookup, OriginalJobKindLookupStep, abi, builtin_factory, close_body, close_original, has_owned_jobs, register_bounded_job_kind, start_job};
use crate::tests::{delta, loan, owner_for, warm_registry};
use crate::registry_driver::{slot_grant, source_grant};
use semio_framework_value_derive::{FromValue, ToValue};
use std::future::Future;
use semio_framework_actor::OriginalJobStep as JobStep;
use semio_framework::kernel::OriginalJobSource as OriginalJobAdmission;
use semio_framework_job::{Generation, OperationId};
use semio_framework_value::{RetainedCloneGrant, RetainedCloneProgress};
use semio_plugin_testing_laws::OriginalWorkFixture;

/// 🧫️ Cold authority setup and source construction precede the measured actual registry scope.
#[test]
fn original_job_registry_cold_admission_denial_and_saturation_preserve_sources(){
 let fixture:serde_json::Value=serde_json::from_str(include_str!("../../../../🧩️extension/🧪️tests/🧫️fixtures/📨️invoke/🔣️.json")).unwrap();
 let raw=fixture["text"].as_str().unwrap().repeat(fixture["repeat"].as_u64().unwrap()as usize).into_bytes();
 let g=&fixture["registryGrant"];let grant=RetainedCloneGrant{maximum_items:g["maximumItems"].as_u64().unwrap()as usize,maximum_copy_bytes:g["maximumCopyBytes"].as_u64().unwrap()as usize,maximum_capacity_bytes:g["maximumCapacityBytes"].as_u64().unwrap()as usize,maximum_release_bytes:g["maximumReleaseBytes"].as_u64().unwrap()as usize,maximum_depth:g["maximumDepth"].as_u64().unwrap()as usize};
 let operation=OperationId(fixture["caller"]["operation"].as_u64().unwrap());let generation=Generation(fixture["caller"]["generation"].as_u64().unwrap());let mut owner=owner_for(operation,generation);
 let mut source=Some(OriginalJobAdmission{job:1,kind:JOB_KIND_INFER.into(),input:Some(raw.clone()),checkpoint:None});let original=source.as_ref().unwrap().input.as_ref().unwrap().as_ptr();
 warm_registry();
 let admit=|owner:&mut OriginalWorkFixture,grant:RetainedCloneGrant,source:&mut Option<OriginalJobAdmission>|loan(owner,grant,1,u64::MAX,|cx|{let before=cx.retained_progress();let(result,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||semio_framework_async::poll::resolve_ready(start_job(source,cx)));Ok((result?,delta(cx.retained_progress(),before),heap))}).unwrap();
 for denied in [RetainedCloneGrant{maximum_items:0,..grant},RetainedCloneGrant{maximum_depth:0,..grant}]{
  let(result,progress,heap)=admit(&mut owner,denied,&mut source);
  assert!(!result);assert_eq!(source.as_ref().unwrap().input.as_ref().unwrap().as_ptr(),original);assert_eq!(progress,RetainedCloneProgress::default());assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));
 }
 for job in 1..=JOB_SLOTS as u64{
  if job!=1{source=Some(OriginalJobAdmission{job,kind:JOB_KIND_INFER.into(),input:Some(raw.clone()),checkpoint:None})}
  let pointer=source.as_ref().unwrap().input.as_ref().unwrap().as_ptr();
  let(result,progress,heap)=admit(&mut owner,grant,&mut source);
  assert!(result);assert!(source.is_none());assert_eq!(progress,RetainedCloneProgress{copied_items:1,..Default::default()});assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));
  JOBS.with(|slots|{let slots=slots.borrow();let slot=slots.iter().flatten().find(|slot|slot.job==job).unwrap();assert_eq!(slot.source.as_ref().unwrap().input.as_ref().unwrap().as_ptr(),pointer)});
 }
 source=Some(OriginalJobAdmission{job:JOB_SLOTS as u64+1,kind:JOB_KIND_INFER.into(),input:Some(raw),checkpoint:None});let pointer=source.as_ref().unwrap().input.as_ref().unwrap().as_ptr();
 let(result,progress,heap)=admit(&mut owner,grant,&mut source);
 assert!(!result);assert_eq!(source.as_ref().unwrap().input.as_ref().unwrap().as_ptr(),pointer);assert_eq!(progress,RetainedCloneProgress::default());assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));
 let cleanup=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:64,maximum_capacity_bytes:262144,maximum_release_bytes:262144,maximum_depth:128};
 JOBS.with(|slots|{let mut slots=slots.borrow_mut();for entry in slots.iter_mut(){let Some(slot)=entry.as_mut()else{continue};for _ in 0..10000{let turn=slot_grant(slot,cleanup,true).unwrap();let turn=if slot.body.is_none(){source_grant(turn,&slot.source,&slot.source_close)}else{turn};if loan(&mut owner,turn,1,u64::MAX,|cx|cx.with_original_retirement(|cx|Ok(close_body(slot,cx)?&&close_original(&mut slot.source,&mut slot.source_close,cx)?))).unwrap(){break}}assert!(slot.body.is_none()&&slot.source.is_none()&&slot.source_close.is_none());*entry=None}});
 let mut closing=None;for _ in 0..10000{let turn=source_grant(cleanup,&source,&closing);if loan(&mut owner,turn,1,u64::MAX,|cx|cx.with_original_retirement(|cx|close_original(&mut source,&mut closing,cx))).unwrap(){break}}assert!(source.is_none()&&closing.is_none());owner.finish();
}

/// 🔬️ Every real source and static candidate byte needs its own original copy turn.
#[test]
fn original_job_kind_lookup_preserves_denied_frontiers_and_whole_sources(){
 let fixture:serde_json::Value=serde_json::from_str(include_str!("../../../../🧩️extension/🧪️tests/🧫️fixtures/📨️invoke/🔣️.json")).unwrap();
 let factory=builtin_factory(JOB_KIND_IO_SNIFF).unwrap();for kind in ["semio.artifact-infer","semio.artifact-infer-long","未知","未知🌊x"]{assert!(register_bounded_job_kind(kind,factory))}
 let operation=OperationId(fixture["caller"]["operation"].as_u64().unwrap());let generation=Generation(fixture["caller"]["generation"].as_u64().unwrap());
 let value=&fixture["executionGrant"];let original_grant=RetainedCloneGrant{maximum_items:value["maximumItems"].as_u64().unwrap()as usize,maximum_copy_bytes:value["maximumCopyBytes"].as_u64().unwrap()as usize,maximum_capacity_bytes:value["maximumCapacityBytes"].as_u64().unwrap()as usize,maximum_release_bytes:value["maximumReleaseBytes"].as_u64().unwrap()as usize,maximum_depth:value["maximumDepth"].as_u64().unwrap()as usize};let mut cases=0;
 for row in fixture["lookupCases"].as_array().unwrap(){for copy in [1,3,64]{for cut in [None,Some(0),Some(3),Some(17)]{
  let mut owner=owner_for(operation,generation);let mut source=Some(row["input"].as_str().unwrap().to_string());let pointer=source.as_ref().unwrap().as_ptr();let mut cursor=OriginalJobKindLookup::new();let grant=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:copy,maximum_capacity_bytes:0,maximum_release_bytes:0,maximum_depth:1};let mut terminal=false;
  for turn in 0..10000{
   if cut==Some(turn){owner.cancel().cancel_now()}
   let demand=cursor.demand(source.as_ref().unwrap());let before=(cursor.epoch,cursor.index,cursor.offset,cursor.left,cursor.candidate.map(|candidate|candidate.kind));
   for denied in [RetainedCloneGrant{maximum_items:0,..grant},RetainedCloneGrant{maximum_depth:0,..grant},RetainedCloneGrant{maximum_copy_bytes:0,..grant}]{
    if denied.maximum_items>0&&denied.maximum_depth>0&&demand.maximum_copy_bytes==0{continue}
    let(step,progress,heap)=loan(&mut owner,denied,1,u64::MAX,|cx|{let before=cx.retained_progress();let(step,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||cursor.advance(source.as_ref().unwrap(),cx));Ok((step?,delta(cx.retained_progress(),before),heap))}).unwrap();assert!(matches!(step,OriginalJobKindLookupStep::Pending));assert_eq!(progress,RetainedCloneProgress::default());assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));assert_eq!((cursor.epoch,cursor.index,cursor.offset,cursor.left,cursor.candidate.map(|candidate|candidate.kind)),before);assert_eq!(source.as_ref().unwrap().as_ptr(),pointer);
   }
   let(step,progress,heap)=loan(&mut owner,grant,1,u64::MAX,|cx|{let before=cx.retained_progress();let(step,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||cursor.advance(source.as_ref().unwrap(),cx));Ok((step?,delta(cx.retained_progress(),before),heap))}).unwrap();assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));assert!(progress.fits(grant));assert!(progress.copied_bytes<=1);assert_eq!(source.as_ref().unwrap().as_ptr(),pointer);
   if owner.cancel().is_cancelled_now(){assert!(matches!(step,OriginalJobKindLookupStep::Pending));assert_eq!(progress,RetainedCloneProgress::default());terminal=true;break}
   match step{OriginalJobKindLookupStep::Pending=>{},OriginalJobKindLookupStep::Found(candidate)=>{let expected=row["matched"].as_u64().unwrap()as usize;assert_eq!(candidate.kind,row["candidates"][expected].as_str().unwrap());terminal=true;break},OriginalJobKindLookupStep::Missing=>{assert!(row["matched"].is_null());terminal=true;break}}
  }
  assert!(terminal);let(_,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||drop(cursor));assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));let mut closing=None;let mut emptied=false;
  for _ in 0..10000{let turn=source_grant(RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:copy,..original_grant},&source,&closing);let(result,progress,heap)=loan(&mut owner,turn,1,u64::MAX,|cx|{let before=cx.retained_progress();let(result,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||cx.with_original_retirement(|cx|close_original(&mut source,&mut closing,cx)));Ok((result?,delta(cx.retained_progress(),before),heap))}).unwrap();assert_eq!((heap.requested_bytes,heap.released_bytes),(progress.retained_capacity_bytes,progress.released_bytes));if result{emptied=true;break}}
  assert!(emptied&&source.is_none()&&closing.is_none());owner.finish();cases+=1;
 }}}
}

/// 🛑️ Original cancellation admits only a funded same-identity metadata signal.
#[test]
fn original_job_cancellation_preserves_denied_and_foreign_sources(){
 let fixture:serde_json::Value=serde_json::from_str(include_str!("../../../../🧩️extension/🧪️tests/🧫️fixtures/📨️invoke/🔣️.json")).unwrap();let g=&fixture["registryGrant"];let grant=RetainedCloneGrant{maximum_items:g["maximumItems"].as_u64().unwrap()as usize,maximum_copy_bytes:g["maximumCopyBytes"].as_u64().unwrap()as usize,maximum_capacity_bytes:g["maximumCapacityBytes"].as_u64().unwrap()as usize,maximum_release_bytes:g["maximumReleaseBytes"].as_u64().unwrap()as usize,maximum_depth:g["maximumDepth"].as_u64().unwrap()as usize};let operation=OperationId(fixture["caller"]["operation"].as_u64().unwrap());let generation=Generation(fixture["caller"]["generation"].as_u64().unwrap());let mut owner=owner_for(operation,generation);let mut source=Some(OriginalJobAdmission{job:1,kind:JOB_KIND_INFER.into(),input:Some(fixture["text"].as_str().unwrap().repeat(fixture["repeat"].as_u64().unwrap()as usize).into_bytes()),checkpoint:None});let pointer=source.as_ref().unwrap().input.as_ref().unwrap().as_ptr();
 let signal=|owner:&mut OriginalWorkFixture,grant:RetainedCloneGrant|loan(owner,grant,1,u64::MAX,|cx|{let before=cx.retained_progress();let(result,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||abi::cancel(1,cx));Ok((result,delta(cx.retained_progress(),before),heap))});
 assert!(loan(&mut owner,grant,1,u64::MAX,|cx|Ok(abi::start(&mut source,cx)?)).unwrap());
 for denied in [RetainedCloneGrant{maximum_items:0,..grant},RetainedCloneGrant{maximum_depth:0,..grant}]{let(result,progress,heap)=signal(&mut owner,denied).unwrap();assert!(!result.unwrap());assert_eq!(progress,RetainedCloneProgress::default());assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));JOBS.with(|slots|{let slots=slots.borrow();let original=slots.iter().flatten().find(|slot|slot.job==1).unwrap();assert!(!original.cancelled);assert_eq!(original.source.as_ref().unwrap().input.as_ref().unwrap().as_ptr(),pointer)});}
 for identity in [(OperationId(operation.0+1),generation),(operation,Generation(generation.0+1))]{let mut foreign=owner_for(identity.0,identity.1);let(result,progress,heap)=signal(&mut foreign,grant).unwrap();assert_eq!(result.unwrap_err().kind,semio_framework_value::ValueRefusalKind::OwnershipLimit);assert_eq!(progress,RetainedCloneProgress::default());assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));JOBS.with(|slots|assert!(!slots.borrow().iter().flatten().find(|slot|slot.job==1).unwrap().cancelled));foreign.finish();}
 {let(result,progress,heap)=signal(&mut owner,grant).unwrap();assert!(result.unwrap());assert_eq!(progress,RetainedCloneProgress{copied_items:1,..Default::default()});assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));JOBS.with(|slots|{let slots=slots.borrow();let original=slots.iter().flatten().find(|slot|slot.job==1).unwrap();assert!(original.cancelled);assert_eq!(original.source.as_ref().unwrap().input.as_ref().unwrap().as_ptr(),pointer);assert!(matches!(original.body,Some(JobBody::Resolving(_))));});assert!(!owner.cancel().is_cancelled_now());}
 let g=&fixture["executionGrant"];let cleanup=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:g["maximumCopyBytes"].as_u64().unwrap()as usize,maximum_capacity_bytes:g["maximumCapacityBytes"].as_u64().unwrap()as usize,maximum_release_bytes:g["maximumReleaseBytes"].as_u64().unwrap()as usize,maximum_depth:g["maximumDepth"].as_u64().unwrap()as usize};JOBS.with(|slots|{let mut slots=slots.borrow_mut();let index=slots.iter().position(|slot|slot.as_ref().is_some_and(|slot|slot.job==1)).unwrap();let original=slots[index].as_mut().unwrap();for _ in 0..10000{let turn=slot_grant(original,cleanup,true).unwrap();let turn=if original.body.is_none(){source_grant(turn,&original.source,&original.source_close)}else{turn};let(done,progress,heap)=loan(&mut owner,turn,1,u64::MAX,|cx|cx.with_original_retirement(|cx|{let before=cx.retained_progress();let(done,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||Ok::<_,semio_framework_job::OriginalTurnFailure>(close_body(original,cx)?&&close_original(&mut original.source,&mut original.source_close,cx)?));Ok((done?,delta(cx.retained_progress(),before),heap))})).unwrap();assert_eq!((heap.requested_bytes,heap.released_bytes),(progress.retained_capacity_bytes,progress.released_bytes));if done{break}}assert!(original.body.is_none()&&original.source.is_none()&&original.source_close.is_none());slots[index]=None;});owner.finish();
}

/// 🛑️ Actual canceled controls borrow the initiating token until their terminal paid reply.
#[test]
fn original_job_cancelled_context_publishes_terminal_reply_after_paid_close(){
 warm_registry();
 let corpus:serde_json::Value=serde_json::from_str(include_str!("../../../../🧩️extension/🧪️tests/🧫️fixtures/📨️invoke/🔣️.json")).unwrap();let operation=OperationId(corpus["caller"]["operation"].as_u64().unwrap());let generation=Generation(corpus["caller"]["generation"].as_u64().unwrap());let g=&corpus["executionGrant"];let original=RetainedCloneGrant{maximum_items:g["maximumItems"].as_u64().unwrap()as usize,maximum_copy_bytes:g["maximumCopyBytes"].as_u64().unwrap()as usize,maximum_capacity_bytes:g["maximumCapacityBytes"].as_u64().unwrap()as usize,maximum_release_bytes:g["maximumReleaseBytes"].as_u64().unwrap()as usize,maximum_depth:g["maximumDepth"].as_u64().unwrap()as usize};
 for copy in corpus["failureCopyGrants"].as_array().unwrap().iter().map(|v|v.as_u64().unwrap()as usize){
  let grant=RetainedCloneGrant{maximum_copy_bytes:copy,..original};let mut owner=owner_for(operation,generation);let token=owner.cancel()as*const semio_framework_job::CancelToken;let mut source=Some(OriginalJobAdmission{job:1,kind:JOB_KIND_INFER.into(),input:Some(corpus["text"].as_str().unwrap().repeat(corpus["repeat"].as_u64().unwrap()as usize).into_bytes()),checkpoint:Some(vec![7;257])});
  {let(admitted,progress,heap)=loan(&mut owner,grant,1,u64::MAX,|cx|{let before=cx.retained_progress();let(admitted,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||abi::start(&mut source,cx));Ok((admitted?,delta(cx.retained_progress(),before),heap))}).unwrap();assert!(admitted);assert!(source.is_none());assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));assert_eq!(progress,RetainedCloneProgress{copied_items:1,..Default::default()});}
  owner.cancel().cancel_now();let mut output=None;
  for denied in corpus["jobWorkDenials"].as_array().unwrap(){let before=JOBS.with(|slots|{let slots=slots.borrow();let slot=slots.iter().flatten().find(|slot|slot.job==1).unwrap();(slot.cancellation_signalled,slot.cancellation_fault_started,slot.source.as_ref().unwrap().input.as_ref().unwrap().as_ptr())});let(step,progress,heap)=loan(&mut owner,grant,denied["fuel"].as_u64().unwrap(),denied["deadline"].as_u64().unwrap(),|cx|{let before=cx.retained_progress();let(step,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||abi::step(1,cx));Ok((step?,delta(cx.retained_progress(),before),heap))}).unwrap();assert!(step.is_none());assert_eq!(progress,RetainedCloneProgress::default());assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));JOBS.with(|slots|{let slots=slots.borrow();let slot=slots.iter().flatten().find(|slot|slot.job==1).unwrap();assert_eq!((slot.cancellation_signalled,slot.cancellation_fault_started,slot.source.as_ref().unwrap().input.as_ref().unwrap().as_ptr()),before)});}
  for turn in 0..100000{let funded=loan(&mut owner,grant,1,u64::MAX,|cx|Ok(crate::registry_driver::closing_grant(1,grant,true,cx)?)).unwrap();let(step,progress,heap)=loan(&mut owner,funded,1024,u64::MAX,|cx|{assert!(cx.is_cancelled());assert!(std::ptr::eq(cx.borrowed_original_cancel_token().unwrap(),token));let before=cx.retained_progress();let(step,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||abi::step(1,cx));Ok((step?,delta(cx.retained_progress(),before),heap))}).unwrap();assert!(progress.fits(funded));assert_eq!((heap.requested_bytes,heap.released_bytes),(progress.retained_capacity_bytes,progress.released_bytes));match step{None=>assert!(has_owned_jobs(operation.0,generation.0)),Some(JobStep::Failed(bytes))=>{assert!(!has_owned_jobs(operation.0,generation.0));output=Some(bytes);break},_=>panic!("canceled original job returned another outcome")};assert!(turn<99999,"original canceled context did not finish its paid terminal reply copy={copy}");}
  let decoded:serde_json::Value=semio_os_kernel::os_pack::pack_rt::decode_wire_value(output.as_ref().unwrap()).unwrap().into();assert_eq!(decoded["code"],corpus["cancelledJobReply"]["code"]);assert_eq!(decoded["message"],corpus["cancelledJobReply"]["message"]);let mut closing=None;
  for _ in 0..10000{let turn=source_grant(grant,&output,&closing);let(done,progress,heap)=loan(&mut owner,turn,1,u64::MAX,|cx|{let before=cx.retained_progress();let(done,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||cx.with_original_retirement(|cx|close_original(&mut output,&mut closing,cx)));Ok((done?,delta(cx.retained_progress(),before),heap))}).unwrap();assert_eq!((heap.requested_bytes,heap.released_bytes),(progress.retained_capacity_bytes,progress.released_bytes));if done{break}}assert!(output.is_none()&&closing.is_none());
  let(_,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||drop((output,closing)));assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));owner.finish();
 }
}
